package com.cob.emr.ddd.domain.medicalnote.exception;public class InvalidVisitNumberException extends DomainException {    private final int attemptedVisitNumber;    private final int expectedVisitNumber;    public InvalidVisitNumberException(int attemptedVisitNumber, int expectedVisitNumber) {        super(String.format("Invalid visit number. Attempted: %d, Expected: %d",            attemptedVisitNumber, expectedVisitNumber));        this.attemptedVisitNumber = attemptedVisitNumber;        this.expectedVisitNumber = expectedVisitNumber;    }    public int getAttemptedVisitNumber() {        return attemptedVisitNumber;    }    public int getExpectedVisitNumber() {        return expectedVisitNumber;    }}
